import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class SortingTests:

    def __init__(self, module_name):
        self.module = module_name

    def test_01_bubble_basic(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            arr = [5, 1, 4, 2, 8]
            _test(
                expected=[1, 2, 4, 5, 8],
                actual=self.module.bubble_sort(arr[:]),
                call="bubble_sort([5, 1, 4, 2, 8])"
            )
        except Exception as e:
            print("\u2717 FAILED. bubble_sort basic test raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_02_bubble_edge_cases(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            _test(
                expected=[],
                actual=self.module.bubble_sort([]),
                call="bubble_sort([])"
            )
            _test(
                expected=[1],
                actual=self.module.bubble_sort([1]),
                call="bubble_sort([1])"
            )
            _test(
                expected=[1, 1, 2, 2],
                actual=self.module.bubble_sort([2, 1, 2, 1]),
                call="bubble_sort([2, 1, 2, 1])"
            )
            _test(
                expected=[1, 2, 3, 4, 5],
                actual=self.module.bubble_sort([1, 2, 3, 4, 5]),
                call="bubble_sort(already sorted)"
            )
        except Exception as e:
            print("\u2717 FAILED. bubble_sort edge cases raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

